{"path":"/root/solve.py","content":"#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')


def is_blank(value):
    if value is None:
        return True
    text = str(value).strip()
    return text == '' or text.lower() == 'nan'


def to_float(value):
    if is_blank(value):
        raise ValueError('blank numeric value')
    return float(str(value).strip())


def money(value):
    # Force a JSON float rounded to two decimal places.
    return float(f'{float(value):.2f}')


def read_csv_dict(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))


def load_campaigns(manifest):
    campaigns = []
    for region in manifest.get('regions', []):
        for campaign in region.get('campaigns', []):
            campaigns.append(campaign)
    return campaigns


def latest_billing_row(campaign, billing_rows):
    labels = {campaign.get('campaign_name')}
    labels.update(campaign.get('alias_labels') or [])
    matches = [
        row for row in billing_rows
        if row.get('campaign_label') in labels and row.get('status') == 'active'
    ]
    if not matches:
        raise ValueError(f"No active billing row found for {campaign['campaign_id']}")
    return max(matches, key=lambda row: row.get('cycle_tag', ''))


def build_latest_overrides(location_rows):
    latest = {}
    for row in location_rows:
        if row.get('state') != 'approved':
            continue
        if is_blank(row.get('revision')) or is_blank(row.get('active_clinics')):
            continue
        campaign_id = row.get('campaign_id')
        revision = int(float(str(row['revision']).strip()))
        active_clinics = int(float(str(row['active_clinics']).strip()))
        current = latest.get(campaign_id)
        if current is None or revision > current['revision']:
            latest[campaign_id] = {
                'revision': revision,
                'active_clinics': active_clinics,
            }
    return latest


def calc_model(campaign, payment, active_clinics, crate_cost, days_per_dispatch, dispatches_per_year):
    annual_revenue = payment * active_clinics * dispatches_per_year
    annual_drug_cost = (
        to_float(campaign['drug_cost_per_1000_doses_usd'])
        * active_clinics
        * to_float(campaign['doses_per_day'])
        * days_per_dispatch
        * dispatches_per_year
        / 1000.0
    )
    # Crate cost is per crate per clinic per dispatch.
    annual_crate_cost = crate_cost * active_clinics * dispatches_per_year
    annual_margin = annual_revenue - annual_drug_cost - annual_crate_cost
    return {
        'annual_revenue_usd': annual_revenue,
        'annual_drug_cost_usd': annual_drug_cost,
        'annual_crate_cost_usd': annual_crate_cost,
        'annual_margin_usd': annual_margin,
    }


def main():
    with open(ROOT / 'campaign_manifest.json') as f:
        manifest = json.load(f)

    crate_rows = read_csv_dict(ROOT / 'crate_cost.csv')
    billing_rows = read_csv_dict(ROOT / 'billing.csv')
    location_rows = read_csv_dict(ROOT / 'location_overrides.csv')
    suspension_rows = read_csv_dict(ROOT / 'suspensions.csv')

    crate_cost_by_tier = {
        row['crate_tier']: to_float(row['crate_cost_usd'])
        for row in crate_rows
    }
    hold_campaign_ids = {
        row['campaign_id']
        for row in suspension_rows
        if row.get('suspension_status') == 'hold'
    }
    latest_overrides = build_latest_overrides(location_rows)

    retained = [
        campaign for campaign in load_campaigns(manifest)
        if campaign.get('analysis_flag') == 'review'
        and campaign.get('campaign_id') not in hold_campaign_ids
    ]

    output_campaigns = []
    for campaign in retained:
        billing = latest_billing_row(campaign, billing_rows)
        payment = to_float(billing['payment_per_dispatch_per_clinic_usd'])

        override = latest_overrides.get(campaign['campaign_id'])
        if override is not None:
            active_clinics = override['active_clinics']
        else:
            active_clinics = int(float(str(campaign['default_active_clinics']).strip()))

        crate_tier = campaign['crate_tier']
        if crate_tier not in crate_cost_by_tier:
            raise ValueError(f"No crate cost found for tier {crate_tier!r}")
        crate_cost = crate_cost_by_tier[crate_tier]

        model_6 = calc_model(campaign, payment, active_clinics, crate_cost, 6, 60)
        model_12 = calc_model(campaign, payment, active_clinics, crate_cost, 12, 30)
        margin_difference = model_12['annual_margin_usd'] - model_6['annual_margin_usd']

        output_campaigns.append({
            'campaign_id': campaign['campaign_id'],
            'campaign_name': campaign['campaign_name'],
            'billing_cycle_tag': billing['cycle_tag'],
            'payment_per_dispatch_per_clinic_usd': money(payment),
            'active_clinics': active_clinics,
            'crate_tier': crate_tier,
            'crate_cost_usd': money(crate_cost),
            'annual_revenue_6_day_usd': money(model_6['annual_revenue_usd']),
            'annual_drug_cost_6_day_usd': money(model_6['annual_drug_cost_usd']),
            'annual_crate_cost_6_day_usd': money(model_6['annual_crate_cost_usd']),
            'annual_margin_6_day_usd': money(model_6['annual_margin_usd']),
            'annual_revenue_12_day_usd': money(model_12['annual_revenue_usd']),
            'annual_drug_cost_12_day_usd': money(model_12['annual_drug_cost_usd']),
            'annual_crate_cost_12_day_usd': money(model_12['annual_crate_cost_usd']),
            'annual_margin_12_day_usd': money(model_12['annual_margin_usd']),
            'margin_difference_12_minus_6_usd': money(margin_difference),
        })

    output_campaigns.sort(key=lambda item: item['campaign_id'])

    total_6 = sum(c['annual_margin_6_day_usd'] for c in output_campaigns)
    total_12 = sum(c['annual_margin_12_day_usd'] for c in output_campaigns)
    total_diff = sum(c['margin_difference_12_minus_6_usd'] for c in output_campaigns)
    abs_diff = abs(total_diff)

    decision = 'move_to_12_day' if abs_diff < 11000 else 'keep_6_day'
    if decision == 'move_to_12_day':
        justification = (
            'Absolute total margin difference is below the 11000 USD threshold, '
            'so the 12-day dispatch model is acceptable.'
        )
    else:
        justification = (
            'Absolute total margin difference is at or above the 11000 USD threshold, '
            'so the 6-day dispatch model should be kept.'
        )

    result = {
        'campaigns': output_campaigns,
        'totals': {
            'total_annual_margin_6_day_usd': money(total_6),
            'total_annual_margin_12_day_usd': money(total_12),
            'total_annual_margin_difference_12_minus_6_usd': money(total_diff),
            'absolute_total_margin_difference_usd': money(abs_diff),
        },
        'recommendation': {
            'decision': decision,
            'justification': justification,
        },
    }

    with open(ROOT / 'vaxcrate_analysis.json', 'w') as f:
        json.dump(result, f, indent=2)
        f.write('\n')

    summary_lines = [
        f"Total 6-day margin (USD): {result['totals']['total_annual_margin_6_day_usd']}",
        f"Total 12-day margin (USD): {result['totals']['total_annual_margin_12_day_usd']}",
        f"Absolute difference (USD): {result['totals']['absolute_total_margin_difference_usd']}",
        f"Decision: {decision}",
    ]
    with open(ROOT / 'vaxcrate_summary.md', 'w') as f:
        f.write('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
